// ---- CONFIG — edit these three blocks only ----
// Your WATI API endpoint, no trailing slash. Find it in WATI:
// Settings -> API Docs (looks like https://live-mt-server.wati.io/123456)
const WATI_BASE = 'https://live-mt-server.wati.io/YOUR_TENANT_ID';
// Where admin alerts go — country code first, digits only.
const ADMIN_WHATSAPP = '917373738338';
// Expected total per event, in paise. Guards against price tampering.
const EXPECTED_AMOUNT_PAISE = {
  'Know Thyself · Mussoorie': 17582000
};
// -----------------------------------------------

// The site posts text/plain so the body may arrive as a raw string.
const raw = $input.first().json;
let d = raw.body ?? raw;
if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
if (d && typeof d.data === 'string') { try { d = JSON.parse(d.data); } catch (e) {} }

// WATI wants digits only with the country code: 919876543210
function toWa(phone) {
  let p = String(phone || '').replace(/\D/g, '');
  if (p.length === 10) p = '91' + p;                        // bare Indian mobile
  if (p.length === 11 && p.charAt(0) === '0') p = '91' + p.slice(1);
  return p;
}

return [{
  json: {
    status: d.status || '',
    name: d.name || '',
    email: d.email || '',
    phone: d.phone || '',
    whatsapp: toWa(d.phone),
    event_name: d.event_name || '',
    event_dates: d.event_dates || '',
    amount: d.amount || '',
    amount_display: d.amount_display || '',
    payment_id: d.payment_id || '',
    reason: d.reason || '',
    expected_amount_paise: EXPECTED_AMOUNT_PAISE[d.event_name] || null,
    wati_base: WATI_BASE,
    admin_whatsapp: ADMIN_WHATSAPP
  }
}];

const booking = $('Parse Booking').first().json;
const pay = $input.first().json || {};

const captured = pay.status === 'captured' || pay.status === 'authorized';
const expected = booking.expected_amount_paise;
const amountOk = !expected || pay.amount === expected;
const verified = Boolean(captured && amountOk);

const display = typeof pay.amount === 'number'
  ? '₹' + Number(pay.amount / 100).toLocaleString('en-IN')
  : booking.amount_display;

return [{
  json: {
    ...booking,
    status: verified ? 'booked' : 'unverified',
    amount_display: display,
    verified,
    reason: verified ? '' : ('status=' + (pay.status || 'unknown') + ', amount=' + (pay.amount ?? 'unknown'))
  }
}];
